package com.bank.palindrome;

import java.util.logging.Logger;

// Validates palindrome nicknames for National Bank of India rewards promo.
public class NicknameValidator {
    private static final Logger log = Logger.getLogger(NicknameValidator.class.getName());

    // Two-pointer palindrome check, skipping non-alphanumeric. O(n), O(1).
    public boolean isPalindrome(String nickname) {
        if (nickname == null) {
            throw new IllegalArgumentException("nickname must not be null");
        }
        int left = 0;
        int right = nickname.length() - 1;
        while (left < right) {
            // Skip non-alphanumeric on the left, guarded against crossing.
            while (left < right && !Character.isLetterOrDigit(nickname.charAt(left))) {
                left++;
            }
            // Skip non-alphanumeric on the right, guarded against crossing.
            while (left < right && !Character.isLetterOrDigit(nickname.charAt(right))) {
                right--;
            }
            char lc = Character.toLowerCase(nickname.charAt(left));
            char rc = Character.toLowerCase(nickname.charAt(right));
            if (lc != rc) {
                log.info(() -> "'" + nickname + "' is NOT a palindrome");
                return false;                  // mismatch → not a palindrome
            }
            left++;
            right--;
        }
        log.info(() -> "'" + nickname + "' IS a palindrome");
        return true;
    }
}
