package com.bank.palindrome;

import java.util.logging.ConsoleHandler;
import java.util.logging.Logger;

// Runnable demo: validate several nicknames.
public class NicknameValidatorDemo {
    private static final Logger log = Logger.getLogger(NicknameValidatorDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
    }

    public static void main(String[] args) {
        NicknameValidator validator = new NicknameValidator();

        log.info(() -> "Result = " + validator.isPalindrome("A man, a plan, a canal: Panama"));
        log.info(() -> "Result = " + validator.isPalindrome("Rajesh"));
        log.info(() -> "Result = " + validator.isPalindrome(".,"));    // all punctuation
    }
}
